SET ROLE hub2_mem_owner;
CREATE TABLE mem.text_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,client_id uuid NOT NULL,project_id uuid NOT NULL,idempotency_key text NOT NULL,fingerprint text NOT NULL,body jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(actor_id,idempotency_key));
CREATE FUNCTION mem.save_text_draft(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.text_drafts; BEGIN
IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.upload',d,b);IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended((c->>'actor_id')||'text-draft'||(b->>'idempotency_key'),0));SELECT * INTO r FROM mem.text_drafts WHERE actor_id=(c->>'actor_id')::uuid AND idempotency_key=b->>'idempotency_key';IF FOUND THEN IF r.fingerprint IS DISTINCT FROM d THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='23505';END IF;ELSE IF b->>'idempotency_key' IS NULL OR b->>'text' IS NULL THEN RAISE EXCEPTION 'invalid_text_draft';END IF;PERFORM authz.assert_effect(h);INSERT INTO mem.text_drafts(actor_id,client_id,project_id,idempotency_key,fingerprint,body) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,(c->>'project_id')::uuid,b->>'idempotency_key',d,b) RETURNING * INTO r;PERFORM mem.emit(c,'text.draft_saved',r.id,1,r.id,jsonb_build_object('resume_id',r.id,'size',octet_length(b->>'text'),'sha256',encode(public.digest(b->>'text','sha256'),'hex'),'coverage','draft_retained'));END IF;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',r.id,'resume_id',r.id,'idempotency_key',r.idempotency_key,'state','draft_saved','body',r.body,'upload_operation',(SELECT jsonb_build_object('operation_id',o.id,'state',o.state,'receipt',o.receipt,'attempt',o.attempt,'fencing_token',o.fencing_token,'lease_until',o.lease_until) FROM mem.operations o WHERE o.actor_id=r.actor_id AND o.idempotency_key IN ('text:'||r.id,'text:'||r.id||':new') ORDER BY o.created_at DESC LIMIT 1));END $$;
CREATE FUNCTION mem.text_draft(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;r mem.text_drafts;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.upload',d,b);SELECT * INTO r FROM mem.text_drafts WHERE id=(b->>'resume_id')::uuid AND actor_id=(c->>'actor_id')::uuid AND project_id=(c->>'project_id')::uuid;IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',r.id,'resume_id',r.id,'idempotency_key',r.idempotency_key,'state','draft_saved','body',r.body,'upload_operation',(SELECT jsonb_build_object('operation_id',o.id,'state',o.state,'receipt',o.receipt,'attempt',o.attempt,'fencing_token',o.fencing_token,'lease_until',o.lease_until) FROM mem.operations o WHERE o.actor_id=r.actor_id AND o.idempotency_key IN ('text:'||r.id,'text:'||r.id||':new') ORDER BY o.created_at DESC LIMIT 1));END $$;
CREATE FUNCTION mem.read_range(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;v record;r uuid;offset_byte bigint;end_byte bigint; BEGIN
IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.read',d,b);SELECT cv.*,o.provider,o.bucket,o.object_key,o.provider_version_id,o.availability INTO v FROM mem.content_versions cv JOIN mem.materials m ON m.id=cv.material_id JOIN mem.verified_objects o ON o.id=cv.object_id WHERE cv.material_id=(b->>'material_id')::uuid AND cv.id=(b->>'version_id')::uuid AND m.project_id=(c->>'project_id')::uuid AND mem.version_visible((c->>'actor_id')::uuid,cv.id);IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;offset_byte:=COALESCE((b->>'offset')::bigint,0);IF offset_byte<0 OR offset_byte>v.size OR COALESCE((b->>'limit')::bigint,65536) NOT BETWEEN 1 AND 131072 THEN RAISE EXCEPTION 'invalid_range';END IF;end_byte:=LEAST(v.size,offset_byte+COALESCE((b->>'limit')::bigint,65536));PERFORM authz.assert_effect(h);INSERT INTO mem.read_receipts(actor_id,client_id,material_id,version_id,sha256,range_start,range_end,complete,state) VALUES((c->>'actor_id')::uuid,(c->>'client_id')::uuid,v.material_id,v.id,v.sha256,offset_byte,end_byte,offset_byte=0 AND end_byte=v.size,'prepared') RETURNING id INTO r;
RETURN jsonb_build_object('state','prepared','read_receipt_id',r,'fixed_ref',jsonb_build_object('material_id',v.material_id,'version_id',v.id,'sha256',v.sha256,'size',v.size,'provenance_state',v.provenance_state,'source_stale',mem.version_stale(v.id)),'range',jsonb_build_object('start',offset_byte,'end_exclusive',end_byte),'object',jsonb_build_object('provider',v.provider,'bucket',v.bucket,'key',v.object_key,'version_id',v.provider_version_id));END $$;
REVOKE ALL ON mem.text_drafts FROM PUBLIC,hub2_mem;
REVOKE ALL ON FUNCTION mem.save_text_draft(uuid,text,text),mem.text_draft(uuid,text,text),mem.read_range(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.save_text_draft(uuid,text,text),mem.text_draft(uuid,text,text),mem.read_range(uuid,text,text) TO hub2_mem;
RESET ROLE;

SET ROLE hub2_mem_owner;
CREATE FUNCTION mem.publish_text_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;m mem.materials;v mem.content_versions;r jsonb;ref jsonb; BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501'; END IF; c:=mem.guard(h,'mem.upload',d,b); IF (b->>'project_id')::uuid IS DISTINCT FROM (c->>'project_id')::uuid THEN RAISE EXCEPTION 'resource_mismatch' USING ERRCODE='42501'; END IF; SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; IF o.state='published' THEN PERFORM authz.assert_effect(h);RETURN o.receipt; END IF; IF o.state<>'verified' OR o.lease_until<=clock_timestamp() OR o.fencing_token IS DISTINCT FROM (b->>'fencing_token')::uuid OR o.attempt IS DISTINCT FROM (b->>'attempt')::bigint THEN RAISE EXCEPTION 'lease_conflict' USING ERRCODE='40001'; END IF; SELECT * INTO m FROM mem.materials WHERE id=o.material_id FOR UPDATE; IF m.content_revision<>o.expected_revision OR m.current_version_id IS DISTINCT FROM o.expected_version_id OR m.state<>'active' THEN PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='conflict' WHERE id=o.id; PERFORM authz.assert_effect(h);RETURN jsonb_build_object('operation_id',o.id,'state','conflict','retained_state','verified_candidate','next_step','explicit_rebase_or_branch'); END IF;
PERFORM authz.assert_effect(h); INSERT INTO mem.content_versions(material_id,object_id,sha256,size,actor_id,reason,provenance_state) VALUES(m.id,o.object_id,o.expected_hash,o.expected_size,(c->>'actor_id')::uuid,COALESCE(b->>'reason','publish'),CASE WHEN jsonb_array_length(COALESCE(b->'actual_inputs','[]'))>0 THEN 'declared' WHEN o.origin_kind='agent_processed' THEN 'pending' ELSE 'raw' END) RETURNING * INTO v; FOR ref IN SELECT value FROM jsonb_array_elements(COALESCE(b->'actual_inputs','[]')) LOOP IF NOT EXISTS(SELECT 1 FROM mem.content_versions WHERE id=(ref->>'version_id')::uuid AND material_id=(ref->>'material_id')::uuid AND sha256=ref->>'sha256') THEN RAISE EXCEPTION 'source_reference_mismatch' USING ERRCODE='42501'; END IF;PERFORM mem.assert_version_sources(h,(ref->>'version_id')::uuid,'mem.read');PERFORM authz.assert_effect(h);INSERT INTO mem.source_edges(output_version_id,input_version_id,derivation_kind) VALUES(v.id,(ref->>'version_id')::uuid,'agent_declared_actual_text_input'); END LOOP;PERFORM authz.assert_effect(h); UPDATE mem.materials SET current_version_id=v.id,content_revision=content_revision+1,event_revision=event_revision+1,provenance_state=v.provenance_state WHERE id=m.id RETURNING * INTO m; r:=jsonb_build_object('operation_id',o.id,'state','published','domain_revision',m.event_revision,'content_revision',m.content_revision,'fixed_refs',jsonb_build_array(jsonb_build_object('material_id',m.id,'version_id',v.id,'sha256',v.sha256,'size',v.size)),'business_registration','pending'); PERFORM authz.assert_effect(h); UPDATE mem.operations SET state='published',result_version_id=v.id,receipt=r WHERE id=o.id; PERFORM mem.emit(c,'material.published',m.id,m.event_revision,o.id,r); PERFORM authz.assert_effect(h);RETURN r; END $$;
REVOKE ALL ON FUNCTION mem.publish_text_upload(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.publish_text_upload(uuid,text,text) TO hub2_mem;
RESET ROLE;
SET ROLE hub2_mem_owner;
CREATE FUNCTION mem.claim_text_upload(h uuid,d text,payload text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,mem AS $$ DECLARE b jsonb:=payload::jsonb;c jsonb;o mem.operations;BEGIN IF payload IS NULL OR d IS NULL OR encode(public.digest(payload,'sha256'),'hex') IS DISTINCT FROM d THEN RAISE EXCEPTION 'digest_mismatch' USING ERRCODE='42501';END IF;c:=mem.guard(h,'mem.upload',d,b);SELECT * INTO o FROM mem.operations WHERE id=(b->>'operation_id')::uuid AND project_id=(c->>'project_id')::uuid AND actor_id=(c->>'actor_id')::uuid FOR UPDATE;IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM mem.text_drafts t WHERE t.actor_id=o.actor_id AND o.idempotency_key IN ('text:'||t.id,'text:'||t.id||':new')) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501';END IF;IF o.state='published' THEN PERFORM authz.assert_effect(h);RETURN o.receipt;END IF;IF o.state NOT IN ('prepared','uploading','verifying','verified') THEN RAISE EXCEPTION 'operation_state_conflict' USING ERRCODE='40001';END IF;PERFORM authz.assert_effect(h);UPDATE mem.operations SET state='verifying',attempt=attempt+1,fencing_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '10 minutes' WHERE id=o.id RETURNING * INTO o;RETURN jsonb_build_object('operation_id',o.id,'state',o.state,'attempt',o.attempt,'fencing_token',o.fencing_token,'staging_key',o.staging_key,'lease_until',o.lease_until);END $$;
REVOKE ALL ON FUNCTION mem.claim_text_upload(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION mem.claim_text_upload(uuid,text,text) TO hub2_mem;
RESET ROLE;
